  func MixRgb(surface : Color, tint : Color, weight : int) : Color
  {
    var base = 255 - weight;
    return {
      r: cast UInt8 (((cast int surface.r) * base + (cast int tint.r) * weight + 127) / 255);
      g: cast UInt8 (((cast int surface.g) * base + (cast int tint.g) * weight + 127) / 255);
      b: cast UInt8 (((cast int surface.b) * base + (cast int tint.b) * weight + 127) / 255);
    };
  }

